import{_ as t,o as e,c as l,a2 as i}from"./chunks/framework.BXzK3EA4.js";const o="/img/AI/%E5%AD%A6%E4%B9%A0%E8%AE%A1%E5%88%92/stages.svg",_=JSON.parse('{"title":"学习阶段","description":"Python → LLM API → FastAPI。","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/12-学习阶段.md","filePath":"agent/学习计划/12-学习阶段.md","lastUpdated":1793932732000}'),r={name:"agent/学习计划/12-学习阶段.md"};function n(s,a,d,c,h,p){return e(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="学习阶段" tabindex="-1">学习阶段 <a class="header-anchor" href="#学习阶段" aria-label="Permalink to &quot;学习阶段&quot;">​</a></h1><p><img src="'+o+'" alt="AI 开发四阶段:按依赖顺序推进,每一阶段都能独立跑通再进下一步"></p><h2 id="第一阶段-先把「能调通」打通" tabindex="-1">第一阶段:先把「能调通」打通 <a class="header-anchor" href="#第一阶段-先把「能调通」打通" aria-label="Permalink to &quot;第一阶段:先把「能调通」打通&quot;">​</a></h2><p>Python → LLM API → FastAPI。</p><ul><li>用 uv 建好虚拟环境,装好依赖</li><li>跑通第一个 <code>/chat/completions</code> 调用,搞清楚 token 用量</li><li>用 FastAPI 包一层 HTTP 接口,能被别人调用</li></ul><h2 id="第二阶段-再做「能检索」" tabindex="-1">第二阶段:再做「能检索」 <a class="header-anchor" href="#第二阶段-再做「能检索」" aria-label="Permalink to &quot;第二阶段:再做「能检索」&quot;">​</a></h2><p>RAG → Embedding → pgvector。</p><ul><li>文档加载与分块,确定 chunk 大小与重叠</li><li>算 Embedding 写入 pgvector,建好索引</li><li>检索 top-k 拼进 Prompt,先做个能用的知识库问答</li></ul><h2 id="第三阶段-然后做「能行动」" tabindex="-1">第三阶段:然后做「能行动」 <a class="header-anchor" href="#第三阶段-然后做「能行动」" aria-label="Permalink to &quot;第三阶段:然后做「能行动」&quot;">​</a></h2><p>Agent → Tool Calling → MCP。</p><ul><li>让模型自己决定调用哪个工具、传什么参数</li><li>用 MCP 统一工具接入方式,加新工具不用改 Agent</li><li>工具结果回传后继续推理,直到拿到答案</li></ul><h2 id="最后-把本地模型也接进来" tabindex="-1">最后:把本地模型也接进来 <a class="header-anchor" href="#最后-把本地模型也接进来" aria-label="Permalink to &quot;最后:把本地模型也接进来&quot;">​</a></h2><p>Ollama。</p><p>主流程仍然走 API,只在敏感场景或离线时切到本地模型,顺带把成本压下来。</p><blockquote><p>不要跳阶段:RAG 之前如果 API 调不通,后面每一层都会卡在同一个地方。</p></blockquote><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>四个阶段是<strong>能力递进</strong>:先「能调通」(调模型、拿到输出)→ 再「能检索」(RAG 与知识库)→ 然后「能行动」(工具与 Agent)→ 最后接本地模型。</li><li>顺序不能乱:没调通就谈不上检索,没检索就谈不上可靠,没工具就谈不上 Agent。</li><li>每阶段有明确的<strong>出口条件</strong>(能做到什么才算过关),避免「读完了」当成「会了」。</li><li>本地模型放在最后:它带来的是<strong>部署与性能问题</strong>,不是能力问题,先用云端 API 建立正确认知。</li><li>面试加分:能讲「<strong>我按能力递进排的学习顺序,而不是按框架热度排</strong>」。</li></ul>',17)])])}const g=t(r,[["render",n]]);export{_ as __pageData,g as default};
